using System.Globalization;
using System.Text;

namespace AuthLens.Domain.Text;

/// <summary>Python text semantics SAP Lens v1 relies on. <see cref="Casefold"/>, <see cref="Upper"/> and <see cref="Lower"/> are str.casefold(),
/// str.upper() and str.lower() exactly (full case mappings from the tables generated by
/// tools/casefold_table.py with Python 3.12, so it does not depend on the operating system's ICU version). <see cref="Nfkc"/> is
/// unicodedata.normalize('NFKC'), which needs ICU at runtime (AuthLens builds with InvariantGlobalization off; see <see cref="VerifyRuntime"/>).</summary>
public static class PythonText
{
    private static Lazy<Dictionary<int, string>> Load(string data) => new(() =>
    {
        var map = new Dictionary<int, string>(1600);
        foreach (var pair in data.Split(';'))
        {
            var (from, to) = (pair[..pair.IndexOf(':')], pair[(pair.IndexOf(':') + 1)..]);
            map[int.Parse(from, NumberStyles.HexNumber, CultureInfo.InvariantCulture)] =
                string.Concat(to.Split(' ').Select(cp => char.ConvertFromUtf32(int.Parse(cp, NumberStyles.HexNumber, CultureInfo.InvariantCulture))));
        }
        return map;
    });

    private static readonly Lazy<Dictionary<int, string>> FoldTable = Load(CasefoldTable.Casefold), UpperTable = Load(CasefoldTable.Upper), LowerTable = Load(CasefoldTable.Lower);

    public static string UnicodeVersion => CasefoldTable.UnicodeVersion;

    private static bool Ascii(string value)
    {
        foreach (var c in value) if (c > 0x7f) return false;
        return true;
    }

    private static string Map(string value, Dictionary<int, string> table, bool sigma = false)
    {
        var sb = new StringBuilder(value.Length);
        var runes = value.EnumerateRunes().ToList();
        for (var i = 0; i < runes.Count; i++)
        {
            var rune = runes[i];
            // Python lower(): capital sigma is final (U+03C2) after a cased letter and not before one.
            if (sigma && rune.Value == 0x03A3 && i > 0 && Rune.IsLetter(runes[i - 1]) && (i + 1 == runes.Count || !Rune.IsLetter(runes[i + 1]))) { sb.Append('\u03C2'); continue; }
            if (table.TryGetValue(rune.Value, out var mapped)) sb.Append(mapped);
            else sb.Append(rune.ToString());
        }
        return sb.ToString();
    }

    /// <summary>str.casefold().</summary>
    public static string Casefold(string? value) => string.IsNullOrEmpty(value) ? "" : Ascii(value) ? value.ToLowerInvariant() : Map(value, FoldTable.Value);

    /// <summary>str.upper(): full case mapping (German sharp s and ligatures expand).</summary>
    public static string Upper(string? value) => string.IsNullOrEmpty(value) ? "" : Ascii(value) ? value.ToUpperInvariant() : Map(value, UpperTable.Value);

    /// <summary>str.lower(): full case mapping, with the final sigma rule.</summary>
    public static string Lower(string? value) => string.IsNullOrEmpty(value) ? "" : Ascii(value) ? value.ToLowerInvariant() : Map(value, LowerTable.Value, sigma: true);

    /// <summary>Extension forms used where v1 calls .upper(), .lower() or .casefold().</summary>
    public static string PyUpper(this string value) => Upper(value);
    public static string PyLower(this string value) => Lower(value);
    public static string PyCasefold(this string value) => Casefold(value);

    /// <summary>unicodedata.normalize('NFKC', value).</summary>
    public static string Nfkc(string? value) => (value ?? "").Normalize(NormalizationForm.FormKC);

    /// <summary>Stops startup when the runtime has no usable ICU (globalization-invariant mode forced, or libicu missing): NFKC would then silently differ
    /// from v1 for compatibility characters. Returns the ICU version for the startup log.</summary>
    public static string VerifyRuntime()
    {
        string problem;
        try
        {
            if ("ﬁ Ｆ Ⅻ".Normalize(NormalizationForm.FormKC) == "fi F XII") return CultureInfo.InvariantCulture.CompareInfo.Version is { } v ? $"sort version {v.FullVersion}" : "unknown";
            problem = "Unicode normalization (NFKC) is unavailable";
        }
        catch (PlatformNotSupportedException) { problem = "the runtime is in globalization-invariant mode"; }
        throw new InvalidOperationException($"AuthLens needs ICU for Unicode text handling, but {problem}. Install the ICU libraries (libicu) on Linux and do not set " +
            "DOTNET_SYSTEM_GLOBALIZATION_INVARIANT; Windows 10 1903 or later includes ICU.");
    }
}
